('tasks.mandatory','false','true/false whether or not the tasks module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','4fda5776-6fb3-4758-9bd4-2983a9864df9',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('tasks.started','true','DO NOT MODIFY. true/false whether or not the tasks module has been started.  This is used to make sure modules that were running  prior to a restart are started again','6dfe76e4-09eb-4055-a107-fc34a375a508',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('teleconsultation.mandatory','false','true/false whether or not the teleconsultation module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','601bd8cd-d4cb-434a-a36a-15efe5585975',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('teleconsultation.started','true','DO NOT MODIFY. true/false whether or not the teleconsultation module has been started.  This is used to make sure modules that were running  prior to a restart are started again','b8b2b2d9-8f71-408a-8db1-437c36c2b452',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('user.headerAttributeTypes',NULL,'A comma delimited list of PersonAttributeType names that will be shown on the user dashboard. (not used in v1.5)','4f3f5fea-30eb-4e83-b7ae-9ae8704c09e0',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('user.listingAttributeTypes',NULL,'A comma delimited list of PersonAttributeType names that should be displayed for users in _lists_','ecf4f41a-6690-460e-b765-616b10260a02',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('user.requireEmailAsUsername','false','Indicates whether a username must be a valid e-mail or not.','01bc73a8-08c0-4723-9358-9d02df17a93c','org.openmrs.customdatatype.datatype.BooleanDatatype',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('user.viewingAttributeTypes',NULL,'A comma delimited list of PersonAttributeType names that should be displayed for users when _viewing individually_','14f1663b-19b3-44b2-bf8a-c30431e19598',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('use_patient_attribute.healthCenter','false','Indicates whether or not the \'health center\' attribute is shown when viewing/searching for patients','7dea235a-3efd-40f3-9b3d-e64042043013','org.openmrs.customdatatype.datatype.BooleanDatatype',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('use_patient_attribute.mothersName','false','Indicates whether or not mother\'s name is able to be added/viewed for a patient','0ffb5e2b-9671-41e6-a504-88d02a24ccba','org.openmrs.customdatatype.datatype.BooleanDatatype',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('validation.disable','false','Disables validation of OpenMRS Objects. Only takes affect on next restart. Warning: only do this is you know what you are doing!','346a9dc0-5f6a-462d-9065-85bcc7b62203',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.allowOverlappingVisits','false',NULL,'e0376867-c667-4c81-b82f-f65ec7bfd5c7','org.openmrs.customdatatype.datatype.BooleanDatatype',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.assignmentHandler','org.openmrs.api.handler.ExistingVisitAssignmentHandler',NULL,'c90dd1db-0611-451a-94c4-ac4b0f44035d',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.autoCloseVisitType',NULL,'comma-separated list of the visit type(s) to automatically close','7abb62f4-81a6-4145-ac0d-f01034d666ce',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.enabled','true','Set to true to enable the Visits feature. This will replace the \'Encounters\' tab with a \'Visits\' tab on the dashboard.','9c594c46-482d-48b3-9643-05641111fc9f','org.openmrs.customdatatype.datatype.BooleanDatatype',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.encounterTypeToVisitTypeMapping',NULL,'Specifies how encounter types are mapped to visit types when automatically assigning encounters to visits. e.g 1:1, 2:1, 3:2 in the format encounterTypeId:visitTypeId or encounterTypeUuid:visitTypeUuid or a combination of encounter/visit type uuids and ids e.g 1:759799ab-c9a5-435e-b671-77773ada74e4','c84f289c-3869-4683-9b14-ebc47c374212',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.allowedips',NULL,'A comma-separate list of IP addresses that are allowed to access the web services. An empty string allows everyone to access all ws. \n        IPs can be declared with bit masks e.g. 10.0.0.0/30 matches 10.0.0.0 - 10.0.0.3 and 10.0.0.0/24 matches 10.0.0.0 - 10.0.0.255.','3fb6b257-cc9e-46c4-9286-0783256ad566',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.enableStackTraceDetails','true','If the value of this setting is \"true\", then the details of the stackTrace would be shown in the error response. However, the recommendation is to keep it as \"false\", from the Security perspective, to avoid leaking implementation details.','8afeac68-68b7-4b4e-a68d-52f69bdf3ec7',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.mandatory','false','true/false whether or not the webservices.rest module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','982360d5-9ed6-4970-8691-50e39d3c0205',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.maxResultsAbsolute','100','The absolute max results limit. If the client requests a larger number of results, then will get an error','2ddda473-0ab7-4cfc-9ba6-084f29f94668',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.maxResultsDefault','50','The default max results limit if the user does not provide a maximum when making the web service call.','d9088143-ddf1-4be4-8b22-e63b7af9b7e0',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.quietDocs','true','If the value of this setting is \"true\", then nothing is logged while the Swagger specification is being generated.','b939dff4-8e28-4e50-91d6-9bc577bd6745',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.started','true','DO NOT MODIFY. true/false whether or not the webservices.rest module has been started.  This is used to make sure modules that were running  prior to a restart are started again','c84ff635-8d5b-429e-8d2c-ad92d9049e3b',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.uriPrefix',NULL,'The URI prefix through which clients consuming web services will connect to the web application, should be of the form http://{ipAddress}:{port}/{contextPath}','dfce6a81-63d0-43d6-91b2-edbd14fabf5c',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
